306	  private playShieldChargeEffect(api: GameSceneAPI): void {
307	    const scene = api.scene;
308	    const cx    = api.player.x;
309	    const cy    = api.player.y;
310	
311	    const ring = scene.add.graphics().setDepth(150);
312	    ring.lineStyle(2, SentinelAbility.RED_LIGHT, 1);
313	    ring.strokeEllipse(0, 0, 74, 98);
314	    ring.setPosition(cx, cy);
315	    ring.setScale(1.9);
316	    ring.setAlpha(0);
317	
318	    scene.tweens.add({
319	      targets: ring, scaleX: 1, scaleY: 1, alpha: 1,
320	      duration: 210, ease: 'Quad.easeIn',
321	      onComplete: () => {
322	        scene.tweens.add({ targets: ring, alpha: 0, duration: 160, onComplete: () => ring.destroy() });
323	      },
324	    });
325	
326	    for (let i = 0; i < 5; i++) {
327	      const ox  = Phaser.Math.FloatBetween(-22, 22);
