329	      dot.fillStyle(SentinelAbility.RED_LIGHT, 1);
330	      dot.fillCircle(0, 0, Phaser.Math.Between(2, 4));
331	      dot.setPosition(cx + ox, cy + 18);
332	      scene.tweens.add({
333	        targets: dot, y: cy - Phaser.Math.Between(28, 56), alpha: 0,
334	        duration: Phaser.Math.Between(340, 530), delay: i * 40, ease: 'Quad.easeOut',
335	        onComplete: () => dot.destroy(),
