  bonusInterval: 200,         // 보너스 점수 간격
  bonusScore: 20,             // 보너스 점수
} as const;

export const ARCHIEVE_DESC = {
  basicEffect: `점수 획득 속도 ${1 + ARCHIEVE_PARAMS.scoreMultiplierExtra}배`,
